def table(head,rows,cls=''):
 return '<table class="'+cls+'"><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table>'
def call(t):return '<div class="callout">'+t+'</div>'
def cards(items):return '<div class="grid three">'+''.join(f'<div class="panel"><div class="num">{i+1:02}</div><h3>{a}</h3><p>{b}</p></div>' for i,(a,b) in enumerate(items))+'</div>'
def add(ch,title,lead,body,notes='',cover=False):slides.append(dict(chapter=ch,title=title,lead=lead,body=body,notes=notes,cover=cover))

